+		test('node reference calls in a callback body are charged per visit', () => {
+			const payload = 'x'.repeat(MAX_RESULT_LENGTH / 2);
+			const $ = () => ({ first: () => ({ json: { payload } }) });
+			const visits = Math.ceil(MAX_WORK / payload.length);
+			const run = (count: number) =>
+				nativeOn("{{ $json.list.every(n => $('Source').first().json.payload.length > n) }}", {
+					$json: { list: new Array<number>(count).fill(0) },
+					$,
+				});
+			expect(run(2)).toEqual({ handled: true, value: true });
+			expect(run(visits + 1)).toEqual({ handled: false });
+		});
